// ===== WhaleTrace 自動爬蟲推播 =====
// 每 30 分鐘從 OpenInsider + Finviz 抓最新數據，比對上一輪，推播新信號

const TRACKERS = ['AAPL','MSFT','NVDA','GOOGL','META','AMZN','TSLA','JPM','V','WMT'];

// ===== 1. 抓 Finviz 快照 =====
const finvizCache = {};
for (const t of TRACKERS) {
  try {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://finviz.com/quote.ashx?t=${t}`,
      headers: { 'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36' },
      timeout: 10000,
      returnFullResponse: false
    });
    const instMatch = html.match(/Institutional Ownership<\/div><\/td>\s*<td[^>]*>\s*<div[^>]*>\s*<b>\s*([\d.]+%)/);
    const shortMatch = html.match(/Short Float<\/div><\/td>\s*<td[^>]*>\s*<div[^>]*>\s*<b>\s*([\d.]+%)/);
    const rsiMatch = html.match(/RSI \(14\)<\/div><\/td>\s*<td[^>]*>\s*<div[^>]*>\s*<b>\s*([\d.]+)/);
    finvizCache[t] = {
      instOwn: instMatch ? instMatch[1] : 'N/A',
      shortFloat: shortMatch ? shortMatch[1] : 'N/A',
      rsi: rsiMatch ? rsiMatch[1] : 'N/A',
    };
  } catch (e) { finvizCache[t] = { instOwn: 'ERR', shortFloat: 'ERR', rsi: 'ERR' }; }
}

// ===== 2. 抓 OpenInsider 內部人交易 =====
let allTrades = [];
try {
  const url = 'http://openinsider.com/screener?s=&o=&pl=&ph=&ll=&lh=&fd=7&fdr=&td=0&tdr=&fdlyl=&fdlyh=&daysago=&xp=1&xs=1&vl=&vh=&ocl=&och=&sic1=-1&sicl=100&sich=9999&grp=0&nfl=&nfh=&nil=&nih=&nol=&noh=&v2l=&v2h=&oc2l=&oc2h=&sortcol=0&cnt=30&page=1';
  const html = await this.helpers.httpRequest({
    method: 'GET', url: url,
    headers: { 'User-Agent': 'Mozilla/5.0' },
    timeout: 15000, returnFullResponse: false
  });
  // Simple table row extraction
  const rows = html.match(/<tr[^>]*>(.*?)<\/tr>/gs) || [];
  for (const row of rows) {
    const cells = row.match(/<td[^>]*>(.*?)<\/td>/gs) || [];
    if (cells.length < 10) continue;
    const clean = cells.map(c => c.replace(/<[^>]+>/g, '').trim());
    const ticker = clean[2] || '';
    if (!TRACKERS.includes(ticker.toUpperCase())) continue;
    allTrades.push({
      ticker: ticker.toUpperCase(),
      insider: clean[4] || '',
      title: clean[5] || '',
      type: clean[6] || '',
      price: clean[7] || '',
      qty: clean[8] || '',
      value: clean[11] || '',
      date: clean[1] || clean[0] || '',
    });
  }
} catch (e) { allTrades = []; }

// ===== 3. 讀取上一輪快取 =====
const prevCache = $getWorkflowStaticData('global');
const prevIds = prevCache.lastTradeIds || [];
const prevShort = prevCache.shortAlerts || {};

// ===== 4. 偵測新內部人交易 =====
const newTrades = allTrades.filter(t => {
  const id = `${t.ticker}_${t.insider}_${t.date}`;
  return !prevIds.includes(id);
});

// 偵測新放空警報 (>5% short float)
const newShortAlerts = [];
for (const t of TRACKERS) {
  const sf = parseFloat(finvizCache[t]?.shortFloat || '0');
  const prev = prevShort[t] || 0;
  if (sf > 5 && sf !== prev) {
    newShortAlerts.push({ ticker: t, shortFloat: sf, prevShort: prev });
  }
}

// ===== 5. 更新快取 =====
prevCache.lastTradeIds = allTrades.map(t => `${t.ticker}_${t.insider}_${t.date}`);
for (const t of TRACKERS) {
  prevCache.shortAlerts[t] = parseFloat(finvizCache[t]?.shortFloat || '0');
}

// ===== 6. 組裝 Telegram 訊息 =====
const now = new Date();
const timeStr = now.toISOString().replace('T',' ').slice(0,19);

let message = `🐋 *WhaleTrace v2.0 自動推播*\n`;
message += `⏰ ${timeStr} UTC\n\n`;

if (newTrades.length > 0) {
  message += `🆕 *新內部人交易 (${newTrades.length}筆)*\n`;
  for (const t of newTrades.slice(0, 5)) {
    const emoji = t.type.includes('Purchase') ? '🟢' : t.type.includes('Sale') ? '🔴' : '⚪';
    message += `${emoji} *${t.ticker}* ${t.insider} (${t.title})\n`;
    message += `  ${t.type} ${t.qty}股 @ $${t.price} = ${t.value}\n`;
  }
  if (newTrades.length > 5) message += `  ...還有 ${newTrades.length-5} 筆\n`;
  message += '\n';
}

if (newShortAlerts.length > 0) {
  message += `⚠️ *放空警報*\n`;
  for (const s of newShortAlerts) {
    message += `🔴 *${s.ticker}* 放空比例 ${s.shortFloat}%\n`;
  }
  message += '\n';
}

if (newTrades.length === 0 && newShortAlerts.length === 0) {
  message += `✅ 無新信號\n`;
}

// 快照摘要
message += `📊 *追蹤摘要*\n`;
for (const t of TRACKERS.slice(0, 5)) {
  const d = finvizCache[t];
  if (d && d.instOwn !== 'ERR') {
    message += `${t}: 機構${d.instOwn} | 放空${d.shortFloat} | RSI ${d.rsi}\n`;
  }
}
message += `\n🔗 [查看詳情](https://james0015-pro.github.io/whaletrace/)`;

return [{ json: { message, hasSignal: newTrades.length > 0 || newShortAlerts.length > 0 } }];
